mapper.select:
SELECT order_id
FROM vi_payment_order
WHERE out_trade_no = #{trade}

mapper.update:
UPDATE vi_quota_slot
SET held_quota = held_quota-#{quantity},
  version = version+1,
  updated_at = UTC_TIMESTAMP(3)
WHERE id = #{slotId}
  AND held_quota >= #{quantity}

UPDATE vi_payment_order
SET refund_reserved_fen = refund_reserved_fen-#{amount},
  refunded_fen = refunded_fen+

    #{amount}
    0
  ,
version = version+1,
updated_at = UTC_TIMESTAMP(3)
WHERE id = #{paymentId}
  AND refund_reserved_fen >= #{amount}
  AND paid_fen >= refunded_fen+#{amount}
